begin;
select no_plan();
alter table public.clinics alter constraint clinics_owner_profile_fk deferrable initially deferred;
insert into auth.users(id) values ('ea000000-0000-4000-8000-000000000001'),('ea000000-0000-4000-8000-000000000002');
insert into public.clinics(id,name,owner_profile_id) values ('ea000000-0000-4000-8000-000000000010','Artificial save clinic','ea000000-0000-4000-8000-000000000001');
insert into public.profiles(id,clinic_id,name,role,status) values ('ea000000-0000-4000-8000-000000000001','ea000000-0000-4000-8000-000000000010','Artificial admin','admin','active'),('ea000000-0000-4000-8000-000000000002','ea000000-0000-4000-8000-000000000010','Artificial reception','reception','active');
set constraints all immediate;
insert into public.units(id,clinic_id,name) values ('ea000000-0000-4000-8000-000000000020','ea000000-0000-4000-8000-000000000010','Artificial unit');
insert into public.profile_units(profile_id,unit_id) values ('ea000000-0000-4000-8000-000000000002','ea000000-0000-4000-8000-000000000020');
insert into public.profile_permissions(profile_id,module,can_view,can_edit) values ('ea000000-0000-4000-8000-000000000002','enrollments',true,true),('ea000000-0000-4000-8000-000000000002','patients',true,true) on conflict(profile_id,module) do update set can_view=true,can_edit=true;
insert into public.patients(id,clinic_id,primary_unit_id,name) values ('ea000000-0000-4000-8000-000000000040','ea000000-0000-4000-8000-000000000010','ea000000-0000-4000-8000-000000000020','Artificial patient');
insert into public.plans(id,clinic_id,name,kind,price_cents,sessions_included,duration_days) values ('ea000000-0000-4000-8000-000000000050','ea000000-0000-4000-8000-000000000010','Artificial plan','monthly',10000,8,30),('ea000000-0000-4000-8000-000000000051','ea000000-0000-4000-8000-000000000010','Artificial second plan','package',20000,24,90);
insert into public.rooms(id,clinic_id,unit_id,name) values ('ea000000-0000-4000-8000-000000000060','ea000000-0000-4000-8000-000000000010','ea000000-0000-4000-8000-000000000020','Artificial room');
insert into public.professionals(id,clinic_id,name) values ('ea000000-0000-4000-8000-000000000061','ea000000-0000-4000-8000-000000000010','Artificial professional');
insert into public.services(id,clinic_id,name,duration_minutes,price_cents) values ('ea000000-0000-4000-8000-000000000062','ea000000-0000-4000-8000-000000000010','Artificial service',60,10000);
insert into public.group_slots(id,clinic_id,unit_id,room_id,professional_id,service_id,name,weekdays,starts_at,duration_minutes,capacity) values ('ea000000-0000-4000-8000-000000000063','ea000000-0000-4000-8000-000000000010','ea000000-0000-4000-8000-000000000020','ea000000-0000-4000-8000-000000000060','ea000000-0000-4000-8000-000000000061','ea000000-0000-4000-8000-000000000062','Artificial group',array[1,3]::smallint[],'08:00',60,3);
create function pg_temp.enroll_input() returns jsonb language sql as $$ select '{"patient_id":"ea000000-0000-4000-8000-000000000040","unit_id":"ea000000-0000-4000-8000-000000000020","plan_id":"ea000000-0000-4000-8000-000000000050","starts_at":"2026-10-08","due_day":15}'::jsonb $$;
select set_config('request.jwt.claim.sub','ea000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select lives_ok($$select public.save_enrollment(pg_temp.enroll_input(),gen_random_uuid())$$,'Reception creates enrollment and charge atomically');
select is((select count(*) from public.enrollments),1::bigint,'One enrollment');
select lives_ok($$select public.save_enrollment(pg_temp.enroll_input(),gen_random_uuid())$$,'Retry succeeds');
select is((select count(*) from public.enrollments),1::bigint,'Retry creates no duplicate');
select is((select count(*) from public.charges),0::bigint,'Reception cannot read financial charges');
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"discount_cents":10000}',gen_random_uuid())$$,'P0001','ENROLLMENT_PRICE_UNAVAILABLE','Zero total rejected');
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"ends_at":"2026-10-01"}',gen_random_uuid())$$,'P0001','INVALID_PERIOD','Invalid period rejected');
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"group_slot_id":"ea000000-0000-4000-8000-000000000099"}',gen_random_uuid())$$,'P0001','AGENDA_FORBIDDEN','Group needs agenda permission');
select throws_ok($$select public.save_enrollment('{"sessions_used":9}',gen_random_uuid(),(select id from public.enrollments limit 1))$$,'P0001','INVALID_SESSION_COUNT','Session overflow rejected');
select lives_ok($$select public.save_enrollment('{"sessions_used":2,"ends_at":null}',gen_random_uuid(),(select id from public.enrollments limit 1))$$,'Session edit and blank end accepted');
select lives_ok($$select public.save_enrollment('{"plan_id":"ea000000-0000-4000-8000-000000000051"}',gen_random_uuid(),(select id from public.enrollments limit 1))$$,'Unpaid plan change succeeds');
reset role;
select is((select count(*) from public.charges where enrollment_id in (select id from public.enrollments where clinic_id='ea000000-0000-4000-8000-000000000010')),1::bigint,'One charge after retry');
select is((select amount_cents from public.charges where clinic_id='ea000000-0000-4000-8000-000000000010'),20000,'Unpaid charge repriced with plan');
select is((select coverage_to from public.charges where clinic_id='ea000000-0000-4000-8000-000000000010'),'2026-12-31'::date,'Coverage follows changed plan');
update public.charges set paid_cents=100,status='partial' where clinic_id='ea000000-0000-4000-8000-000000000010';
set local role authenticated;
select throws_ok($$select public.save_enrollment('{"plan_id":"ea000000-0000-4000-8000-000000000050"}',gen_random_uuid(),(select id from public.enrollments limit 1))$$,'P0001','ENROLLMENT_HAS_PAYMENTS','Paid charge prevents commercial change');
select is((select plan_id from public.enrollments limit 1),'ea000000-0000-4000-8000-000000000051'::uuid,'Rejected commercial change preserves plan');
select throws_ok($$select public.save_enrollment('{"discount_cents":5000}',gen_random_uuid(),(select id from public.enrollments limit 1))$$,'P0001','INVALID_ENROLLMENT_INPUT','Direct RPC cannot change unapproved commercial fields');
select lives_ok($$select public.save_enrollment('{"sessions_used":3}',gen_random_uuid(),(select id from public.enrollments limit 1))$$,'Paid enrollment allows session edits');
reset role;
-- Force failure after the enrollment insert to prove transaction rollback.
create function pg_temp.fail_charge() returns trigger language plpgsql as $$ begin raise exception 'ARTIFICIAL_CHARGE_FAILURE'; end $$;
create trigger artificial_charge_failure before insert on public.charges for each row execute function pg_temp.fail_charge();
set local role authenticated;
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input(),gen_random_uuid())$$,'P0001','ARTIFICIAL_CHARGE_FAILURE','Charge failure aborts entire enrollment');
select is((select count(*) from public.enrollments),1::bigint,'Failed charge leaves no orphan enrollment');
reset role;
drop trigger artificial_charge_failure on public.charges;
insert into public.profile_permissions(profile_id,module,can_view,can_edit) values ('ea000000-0000-4000-8000-000000000002','agenda',true,true) on conflict(profile_id,module) do update set can_view=true,can_edit=true;
set local role authenticated;
select lives_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"group_slot_id":"ea000000-0000-4000-8000-000000000063"}',gen_random_uuid())$$,'Enrollment charge and group saved together');
select lives_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"group_slot_id":"ea000000-0000-4000-8000-000000000063"}',gen_random_uuid())$$,'Group retry is idempotent');
select is((select count(*) from public.group_slot_memberships),1::bigint,'Retry does not duplicate membership');
select lives_ok($$insert into public.patients(clinic_id,primary_unit_id,name,email) values ('ea000000-0000-4000-8000-000000000010','ea000000-0000-4000-8000-000000000020','Artificial new patient','synthetic@example.invalid')$$,'Reception creates patient under RLS');
select lives_ok($$update public.patients set email=null,birth_date=null,notes=null where name='Artificial new patient'$$,'Reception clears optional patient fields');
select is((select email from public.patients where name='Artificial new patient'),null::text,'Optional field actually cleared');
reset role;
set local role authenticated;
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"unit_id":"ea000000-0000-4000-8000-000000000099"}',gen_random_uuid())$$,'P0001','UNIT_FORBIDDEN','Inaccessible unit rejected');
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"patient_id":"ea000000-0000-4000-8000-000000000099"}',gen_random_uuid())$$,'P0001','PATIENT_NOT_FOUND','Unscoped patient rejected');
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input() || '{"plan_id":"ea000000-0000-4000-8000-000000000099"}',gen_random_uuid())$$,'P0001','PLAN_NOT_FOUND','Unscoped plan rejected');
reset role;
update public.profile_permissions set can_edit=false where profile_id='ea000000-0000-4000-8000-000000000002' and module='enrollments';
set local role authenticated;
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input(),gen_random_uuid())$$,'P0001','FORBIDDEN','Missing edit grant rejected');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select throws_ok($$select public.save_enrollment(pg_temp.enroll_input(),gen_random_uuid())$$,'42501',null,'Anonymous cannot call RPC');
reset role;
select * from finish();
rollback;
